package com.zhibrary.waitlist;
import com.zhibrary.book.Book; import com.zhibrary.user.User; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="waitlist_entries") public class WaitlistEntry { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private User user; @ManyToOne(optional=false) private Book book; @Column(nullable=false) private LocalDate requestedDate=LocalDate.now(); private boolean claimed; protected WaitlistEntry(){} public WaitlistEntry(User user,Book book){this.user=user;this.book=book;} public Long getId(){return id;} public User getUser(){return user;} public Book getBook(){return book;} public LocalDate getRequestedDate(){return requestedDate;} public boolean isClaimed(){return claimed;} public void claim(){claimed=true;} }
